# Verify "folding/unfolding": fold = reflection about rectangle repeated. For each outside point, reflect its
# position about the rectangle's four edges iteratively until it falls INSIDE the rectangle; if it lands ON a face,
# keep that face cell (first hit?). Test: simple version: keep reflecting until inside; record every intermediate
# face-touch as we go and see if all fall on the perimeter.
def unfold(p,R0,R1,C0,C1,H,W):
    r,c,pv=p
    # reflect vertically until inside rows: mirror about R0 then R1 alternating
    def fold1(x,a,b):  # reflect about a then b until inside [a,b]
        x=x%(b-a)
        if x>a: x=b-x
        # now x in [a,b]? x can exceed b due to >b-a; clamp: x=min(x,b)
        return min(max(x,a),b)
    def fold2(x,l,r):
        x%= (r-l)
        if x>r: x=r-x
        return min(max(x,l),r)
    rr=fold1(r,R0,R1); cc=fold2(c,C0,C1)
    return rr,cc
