def solve(I, mode='first'):
    I=np.array(I); bg=int(I[0][0]); H,W=I.shape
    colors={v:[(r,c) for r in range(H) for c in range(W) if I[r,c]==v] for v in set(int(x) for x in I.flat)-{bg}}
    bbs={v:(min(p[0] for p in ps),max(p[0] for p in ps),min(p[1] for p in ps),max(p[1] for p in ps)) for v,ps in colors.items()}
    R0=min(b[0] for b in bbs.values()); C0=min(b[2] for b in bbs.values())
    Hout=max(b[1]-b[0]+1 for b in bbs.values()); Wout=max(b[3]-b[2]+1 for b in bbs.values())
    out=[[bg]*Wout for _ in range(Hout)]
    # claims: list of (canvas pos, color)
    claims=[]
    for v,(rr0,rr1,cc0,cc1) in bbs.items():
        for r,c in colors[v]: claims.append((r-rr0,c-cc0,v))
    claims.sort()
    occupied=set()
    for pos,v in claims:
        if mode=='first' and pos not in occupied: out[pos[0]][pos[1]]=v; occupied.add(pos)
        elif mode=='last': out[pos[0]][pos[1]]=v
    return out
